   435  // Validate post-processing flags
   436  bool Importer::ValidateFlags(unsigned int pFlags) const {
   437      ASSIMP_BEGIN_EXCEPTION_REGION();
   438      // run basic checks for mutually exclusive flags
   439      if(!_ValidateFlags(pFlags)) {
   440          return false;
   441      }
   442
   443      // ValidateDS does not anymore occur in the pp list, it plays an awesome extra role ...
   444  #ifdef ASSIMP_BUILD_NO_VALIDATEDS_PROCESS
   445      if (pFlags & aiProcess_ValidateDataStructure) {
   446          return false;
   447      }
   448  #endif
   449      pFlags &= ~aiProcess_ValidateDataStructure;
   450
   451      // Now iterate through all bits which are set in the flags and check whether we find at least
   452      // one pp plugin which handles it.
   453      for (unsigned int mask = 1; mask < (1u << (sizeof(unsigned int)*8-1));mask <<= 1) {
   454
   455          if (pFlags & mask) {
   456
   457              bool have = false;
   458              for( unsigned int a = 0; a < pimpl->mPostProcessingSteps.size(); a++)   {
   459                  if (pimpl->mPostProcessingSteps[a]-> IsActive(mask) ) {
   460
   461                      have = true;
   462                      break;
   463                  }
   464              }
   465              if (!have) {
   466                  return false;
   467              }
   468          }
   469      }
   470      ASSIMP_END_EXCEPTION_REGION(bool);
   471      return true;
   472  }
