   475  const aiScene* Importer::ReadFileFromMemory( const void* pBuffer,
   476      size_t pLength,
   477      unsigned int pFlags,
   478      const char* pHint /*= ""*/) {
   479      ai_assert(nullptr != pimpl);
   480
   481      ASSIMP_BEGIN_EXCEPTION_REGION();
   482      if (!pHint) {
   483          pHint = "";
   484      }
   485
   486      if (!pBuffer || !pLength || strlen(pHint) > MaxLenHint ) {
   487          pimpl->mErrorString = "Invalid parameters passed to ReadFileFromMemory()";
   488          return nullptr;
   489      }
   490
   491      // prevent deletion of the previous IOHandler
   492      IOSystem* io = pimpl->mIOHandler;
   493      pimpl->mIOHandler = nullptr;
   494
   495      SetIOHandler(new MemoryIOSystem((const uint8_t*)pBuffer,pLength,io));
   496
   497      // read the file and recover the previous IOSystem
   498      static const size_t BufSize(Importer::MaxLenHint + 28);
   499      char fbuff[BufSize];
   500      ai_snprintf(fbuff, BufSize, "%s.%s",AI_MEMORYIO_MAGIC_FILENAME,pHint);
   501
   502      ReadFile(fbuff,pFlags);
   503      SetIOHandler(io);
   504
   505      ASSIMP_END_EXCEPTION_REGION_WITH_ERROR_STRING(const aiScene*, pimpl->mErrorString);
   506      return pimpl->mScene;
   507  }
